class NeighborSum {
    vector<vector<int>> grid;
    vector<pair<int,int>> position;
    int n;
    int calculate(int value, bool diagonal) {
        int r = position[value].first, c = position[value].second;
        int result = 0;
        for (int dr = -1; dr <= 1; ++dr) {
            for (int dc = -1; dc <= 1; ++dc) {
                if (abs(dr) + abs(dc) != (diagonal ? 2 : 1)) continue;
                int nr = r + dr, nc = c + dc;
                if (nr >= 0 && nr < n && nc >= 0 && nc < n)
                    result += grid[nr][nc];
            }
        }
        return result;
    }
public:
    NeighborSum(vector<vector<int>>& input) : grid(input), n(input.size()) {
        position.resize(n * n);
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                position[grid[i][j]] = {i, j};
    }
    int adjacentSum(int value) { return calculate(value, false); }
    int diagonalSum(int value) { return calculate(value, true); }
};
